// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Liminal Spaces".

Although it may look 3D, there is no raymarching involved. It's a
variation of one of the very first shaders on Shadertoy, created
by IQ himself. He explains why this effect works.

Deform - fly
https://www.shadertoy.com/view/XsX3Rn

Paul J. Karlik designed the pattern. He spent over a year exploring
the Truchet pattern and building a stunning collection of shaders.
Take a few minutes to explore the vast array of phenomenally beautiful
shader creations here:

https://www.shadertoy.com/user/byt3_m3chanic
*/

let theShader, dpr = Math.max(1, 0.5*window.devicePixelRatio), ww = window.innerWidth*dpr, wh = window.innerHeight*dpr;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2667747/files/vert.glsl', 'frag.glsl');
}

function setup() {
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	canvas.style = canvasStyle;
}

function draw() {
  shader(theShader);
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; 
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
* Tip: For syntax highlighting, paste the code here:
* https://shadered.org/app?fork=4Y3P9GQID0
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define S smoothstep
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define hue(a) (.5+.5*sin(3.14*(a)+vec3(1,2,3)))
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// by Paul J. Karlik (byt3_m3chanic)
// https://codepen.io/pjkarlik/pen/YzQKMWX
vec3 truchet(vec2 p, float side) {
	vec2 grid=fract(p.xy)-.5, id=floor(p.xy);

	float px=fwidth(length(p)-1.), hs=rnd(id);
	if(hs>.5) grid.x*=-1.;

	vec3 bc=vec3(.05), h=hue(side*length(p.x+50.)*.12); 
	h=clamp(h+.45,vec3(0),vec3(1));
	float chk=mod(id.y+id.x,2.)*2.-1.;

	vec2
	d2=vec2(length(grid-.5),length(grid+.5)),
	gx=d2.x<d2.y?vec2(grid-.5):vec2(grid+.5);

	float circle=length(gx)-.5,
	l1=.025+.065*cos(p.x*3.25),
	l2=.085+.065*sin(p.x*3.25),
	l3=.085+.065*sin(p.x*2.25),
	circle2=abs(abs(circle)-l1)-(l2);

	circle2=S(-px,px,circle2);

	// color flip for every other one and then ones 
	// thats are flipped by the hash
	circle=(chk>0.^^ hs>.5) ? S(-px,px,circle) : S(px,-px,circle);

	vec2 sx=abs(grid)-.5;
	float cbx=length(sx)-.1;
	cbx=abs(cbx)-(l3*.75);
	cbx=S(px,-px,cbx);

	h=mix(h,bc,min(circle2,circle));
	h=mix(h,bc,cbx);
	return h;
}
void main() {
	vec2 uv=2.*FC/R-1.;
	uv*=rot(T*.1);
	vec2 p=vec2(uv.x,1)/abs(uv.y)+T;
	vec3 col=S(1.,.0,truchet(p+sign(uv.y)*6.3,3.14*sign(uv.y)))*S(.0,.4,abs(uv.y));
	col=tanh(col);
	col=S(.0,1.,col);
	col=mix(col,vec3(0),pow(dot(uv,uv*.45),1.8));
	col=mix(vec3(0),col,min(time*.3,1.));
	O=vec4(col,1);
}

